def stage_dir(name):
    d = RES / name
    d.mkdir(parents=True, exist_ok=True)
    return d


def savefig(fig, name):
    import matplotlib.pyplot as plt
    FIG.mkdir(parents=True, exist_ok=True)
    p = FIG / f"{name}.png"
    if fig.get_layout_engine() is None:      # constrained layouts keep their own space for colour bars
        fig.tight_layout()
    fig.savefig(p, dpi=130)
    plt.close(fig)
    print("wrote", p, flush=True)


def wrote(p):
    print("wrote", p, flush=True)


def device():
    import torch
    return torch.device("mps" if torch.backends.mps.is_available() else "cpu")


# ---- grains and the test gate -------------------------------------------------
def load_grains():
    """Train and validation grains only. Test rows are reachable only through load_split('test')."""
    g = pd.read_parquet(DERIVED / "grains.parquet")
    return g[g["split"] != "test"].reset_index(drop=True)


def _stack_files():
    f, out = sys._getframe(2), []
    while f is not None:
        out.append(Path(f.f_code.co_filename).name)
        f = f.f_back
    return out


def _gate():
    """Raise unless a permitted stage is on the call stack and the freeze file exists. Returns frozen hash."""
    names = _stack_files()
    ok = [n for n in names if n in READERS and (n != "08_routing.py" or "--score" in sys.argv)]
    if not ok:
        raise PermissionError("test split read refused: caller is not stage 7, 8 --score or 9")
    if not FROZEN.exists():
        raise PermissionError(f"test split read refused: {FROZEN} missing (run make freeze)")
    return ok[0], json.loads(FROZEN.read_text())["hash"]


def digest(p):
    """sha256 of a file's bytes: freeze writes it, the read checks it."""
    return hashlib.sha256(Path(p).read_bytes()).hexdigest()


_STAMP = re.compile(r"^# === AI-GENERATED CODE: PROMPT RECORD START ===$.*?^# === AI-GENERATED CODE: PROMPT RECORD END ===$", re.S | re.M)     # whole lines: the prompts quote both markers mid-line


def code_digest(files):
    """sha256 over the text of files, with the stamped prompt-record block cut out, so make stamp does not move it and an edit to the code does."""
    h = hashlib.sha256()
    for f in files:
        h.update(_STAMP.sub("", Path(f).read_text()).encode())
    return h.hexdigest()


def _unchanged():
    """Raise if the models folder is redirected or a file the freeze hashed has changed. Once per read: _gate also runs per image batch through read_images, so this cannot sit there."""
    if MODELS != DEFAULT_MODELS:
        raise PermissionError(f"test split read refused: models folder is {MODELS}, set by RICE_MODELS_DIR")
    for k, v in json.loads(FROZEN.read_text()).get("parts", {}).items():
        if not (ROOT / k).is_file() or digest(ROOT / k) != v:
            raise PermissionError(f"test split read refused: {k} changed since freeze")


def load_split(name):
    if name != "test":
        g = pd.read_parquet(DERIVED / "grains.parquet")
        return g[g["split"] == name].reset_index(drop=True)
    g = pd.read_parquet(DERIVED / "grains.parquet")
    caller, h = _gate()
    _unchanged()
    TEST_READS.parent.mkdir(parents=True, exist_ok=True)
    new = not TEST_READS.exists()
    with open(TEST_READS, "a", newline="") as f:
        w = csv.writer(f)
        if new: w.writerow(["caller", "time", "frozen_hash"])
        w.writerow([caller, time.strftime("%Y-%m-%dT%H:%M:%S"), h])
    return g[g["split"] == "test"].reset_index(drop=True)


def inner_split(tr):
    """Train rows only, split 80/20 by class and lot: choices validation must not make are fitted on the first frame and scored on the second."""
    from sklearn.model_selection import train_test_split
    a, b = train_test_split(np.arange(len(tr)), test_size=0.2, stratify=tr["class"] + "|" + tr["lot"], random_state=SEED)
    return tr.iloc[a].reset_index(drop=True), tr.iloc[b].reset_index(drop=True)


def xy(df, fs):
    return df[features(fs)].to_numpy(dtype=np.float64), df["y"].to_numpy()


# ---- shuffled-label controls ------------------------------------------------------
CHANCE_BAND = (0.18, 0.22)     # 5 balanced classes: chance is 20%
CONTROL_CEILING = 0.90         # a control that learned the real labels scores near the real accuracy


def shuffled_labels(y, rng):
    """Control labels. Stops the run if the shuffle left the labels in place. A smoke slice is too small to judge, so there it only prints."""
    s = rng.permutation(y)
    kept = float((s == y).mean())
    if not CHANCE_BAND[0] <= kept <= CHANCE_BAND[1]:
        msg = f"CONTROL FAILED: {kept:.2%} of labels unchanged after the shuffle, expected {CHANCE_BAND}"
        if not SMOKE: raise SystemExit(msg)
        print(msg, "(smoke slice, no verdict)", flush=True)
    return s


def control_gate(path):
    """Stops the run if any control row reached the ceiling or has no score. Reads the whole file, so rerunning one model cannot hide another.
    The stop is not the 18-22% band: a simple model can give a whole tight class one shuffled label, so a clean control can sit far from 20%."""
    d = pd.read_csv(path)
    bad = d[~(d["val_accuracy"] < CONTROL_CEILING)]         # an empty score fails too
    if not bad.empty:
        raise SystemExit(f"CONTROL FAILED: {len(bad)} of {len(d)} rows in {path} at or above {CONTROL_CEILING:.0%} or empty\n{bad.to_string()}")
    print(f"controls passed: {len(d)} rows below {CONTROL_CEILING:.0%} in {path}", flush=True)


# ---- image cache ----------------------------------------------------------------
def cache_path():
    return DERIVED / "images128.u8"


def open_cache():
    p = cache_path()
    n = p.stat().st_size // (IMG * IMG * 3)
    return np.memmap(p, dtype=np.uint8, mode="r", shape=(n, IMG, IMG, 3))


_mm = None


def read_images(df):
    """uint8 (n,128,128,3) for the rows of df, in df order. Test rows need a permitted caller."""
    global _mm
    if (df["split"] == "test").any():
        _gate()
    if _mm is None: _mm = open_cache()
    idx = df["row"].to_numpy()
    o = np.argsort(idx, kind="stable")
    out = np.empty((len(idx), IMG, IMG, 3), np.uint8)
    out[o] = _mm[idx[o]]
    return out


def resize128(a):
    from PIL import Image
    return np.asarray(Image.fromarray(a).resize((IMG, IMG), Image.BILINEAR))


def grain_mask(a):
    """Largest Otsu-thresholded component of a uint8 RGB image (bool mask), or None."""
    from scipy import ndimage as ndi
    from skimage.filters import threshold_otsu
    g = 0.2989 * a[..., 0] + 0.5870 * a[..., 1] + 0.1140 * a[..., 2]
    m = g > threshold_otsu(g)
    lab, n = ndi.label(m)
    if n == 0: return None
    sizes = ndi.sum(m, lab, range(1, n + 1))
    return lab == (int(np.argmax(sizes)) + 1)


# ---- grain angle -----------------------------------------------------------------
ANGLE_BANDS = [(0, 10), (10, 20), (20, 30), (30, 45)]   # degrees off the image axes, set by hand before any model was scored by angle; the fold stops at 45
NO_ANGLE = "no_mask"


def off_axis(m):
    """Grain angle from the second moments of its image mask, folded to degrees off the image axes: 0 lies along an axis, 45 is diagonal."""
    yy, xx = np.nonzero(m)
    c = np.cov(xx, yy)
    a = np.degrees(0.5 * np.arctan2(2 * c[0, 1], c[0, 0] - c[1, 1])) % 90
    return min(a, 90 - a)


def angles(df):
    """Off-axis degrees per row, measured on its image; NaN where no usable mask is found. Reads no table column."""
    return np.array([off_axis(m) if m is not None and m.sum() > 2 else np.nan for m in map(grain_mask, read_images(df))])


def angle_band(deg):
    """Band label per angle. Lower edge in, upper edge out, and the top band also holds its upper edge. A row with no angle gets NO_ANGLE."""
    deg = np.asarray(deg, float)
    labels = np.array([f"{lo}-{hi}" for lo, hi in ANGLE_BANDS] + [NO_ANGLE])
    i = np.searchsorted([hi for _, hi in ANGLE_BANDS[:-1]], deg, side="right")
    return labels[np.where(np.isfinite(deg), i, len(ANGLE_BANDS))]


